-- Migration: 202611200011_sprint8o_assessment_permutation.sql
-- Description: Sprint 8O Versioned Assessment Permutation (Revision 2) with Revision 1 Historical Attempt Preservation.
-- Idempotent, transactional, preserves 2-arg submit_curriculum_quiz_attempt RPC signature and RLS boundaries.

alter table public.curriculum_quiz_attempts
  add column if not exists key_revision integer not null default 1
  check (key_revision in (1, 2));

-- Keep default key_revision = 1 so any legacy/Old-App client that omits key_revision
-- is deterministically pinned to Revision 1 and graded against correct_index_v1.
alter table public.curriculum_quiz_attempts
  alter column key_revision set default 1;

alter table private.curriculum_quiz_keys
  add column if not exists correct_index_v1 integer
  check (correct_index_v1 between 0 and 5);

alter table private.curriculum_quiz_keys
  add column if not exists key_revision integer not null default 2
  check (key_revision in (1, 2));

update private.curriculum_quiz_keys
set correct_index_v1 = coalesce(correct_index_v1, correct_index)
where correct_index_v1 is null;

